          "Entity：適用範囲や要件を、IFCのエンティティ型（IFCWALL、IFCDOOR、IFCBEAM）と、必要に応じて定義済みタイプ（predefined type）で絞り込みます。ほとんどの仕様は、まずこのフィルターから始まります。",
          "Attribute：エンティティに直接付いているIFCの属性値（Name、Description、ObjectType、Tag、PredefinedType）をチェックします。属性はプロパティセットとは別物で、チェックの仕方も異なります。",
          "Property：指定したプロパティセット内の、指定したプロパティ（Pset_WallCommon.FireRating、Pset_DoorCommon.IsExternal）をチェックします。最もよく使われるファセットで、データ型の制約や、値のパターンマッチングにも対応しています。",
          "Classification：要素がIfcRelAssociatesClassificationを介して分類参照を持っているかをチェックします。対象はUniclass 2015、OmniClass、NBS、独自の分類体系などで、分類体系の名称やコードのパターンを制約できます。",
          "Material：要素にIfcMaterial、IfcMaterialLayerSet、IfcMaterialConstituentSetのいずれかでマテリアルが割り当てられているかをチェックします。マテリアル名を制約することもでき、耐火性能やサステナビリティの要件に役立ちます。",
          "PartOf：要素が、必要な空間的・論理的な関係に含まれているかをチェックします。階に包含されている、建物システムに集約されている、特定の建物に属している、といった関係です。特定の要素タイプについて、空間階層への準拠を強制するファセットです。",
