        text: "すべてのチームがIDSをゼロから書いているわけではありません。実践的なのは、再利用できるIDSプロファイルのライブラリーを維持するやり方です。たとえば、ステージ3の意匠用、ステージ4の設備（MEP）用、構造の引き渡し用といった具合です。各プロファイルはそのフェーズと分野で最も一般的な要件をカバーし、プロジェクトごとに発注者固有の要件を追加して拡張します。IDSプロファイルは検証エンジンに直接読み込んで組み合わせることができ、同じモデルに対して複数の.idsファイルを実行して、結果を集約できます。",
